package Q5;
import javax.swing.*;import java.awt.*;import java.awt.event.*;
public class EventStyles extends JFrame implements ActionListener{JTextField amount=new JTextField(8);JLabel result=new JLabel("Result");JButton frame=new JButton("Frame listener"),inner=new JButton("Inner class"),anon=new JButton("Anonymous"),lambda=new JButton("Lambda");EventStyles(){setLayout(new FlowLayout());add(amount);for(JButton b:new JButton[]{frame,inner,anon,lambda})add(b);add(result);frame.addActionListener(this);inner.addActionListener(new NamedHandler());anon.addActionListener(new ActionListener(){public void actionPerformed(ActionEvent e){convert();}});lambda.addActionListener(e->convert());amount.addActionListener(e->convert());addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){dispose();}});pack();}public void actionPerformed(ActionEvent e){convert();}class NamedHandler implements ActionListener{public void actionPerformed(ActionEvent e){convert();}}void convert(){try{double v=Double.parseDouble(amount.getText());result.setText(String.format("USD %.2f",v*.012));JOptionPane.showMessageDialog(this,result.getText());}catch(NumberFormatException e){result.setText("Invalid amount");}}public static void main(String[]x){SwingUtilities.invokeLater(()->new EventStyles().setVisible(true));}}
